import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Box3, Vector3, PointLight } = ctx.THREE;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const root = new Group();
  root.name = 'journal-badge';
  root.userData.handlers = {};

  const timelines = [];
  const primitiveCleanups = [];
  const disposables = [];

  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropUv = uv();
  const backdropGradient = smoothstep(0.0, 1.0, backdropUv.y);
  backdropMaterial.colorNode = mix(
    vec3(colors.surface),
    mix(vec3(colors.surface), vec3(colors.ink), backdropGradient),
    0.92
  );
  backdropMaterial.toneMapped = false;

  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMaterial);
  backdrop.name = 'designed-dark-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  backdrop.renderOrder = -20;
  root.add(backdrop);
  disposables.push(backdrop.geometry, backdrop.material);

  const rimLight = new PointLight(colors.accent, 0.78, 4.5, 2);
  rimLight.name = 'signal-red-edge-light';
  rimLight.position.set(0.8, 0.6, 1.35);
  root.add(rimLight);

  const fillLight = new PointLight(colors.paper, 0.32, 5, 2);
  fillLight.name = 'paper-fill';
  fillLight.position.set(-1.4, 0.8, 1.8);
  root.add(fillLight);

  const subject = new Group();
  subject.name = 'machined-metal-badge';
  subject.position.set(0, 0, 0);
  root.add(subject);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  accentMaterial.toneMapped = false;

  const accentRail = new Mesh(new BoxGeometry(0.75, 0.025, 0.035), accentMaterial);
  accentRail.name = 'accent-edge-rail';
  accentRail.position.set(0, 0.34, 0.12);
  accentRail.renderOrder = 8;
  subject.add(accentRail);
  disposables.push(accentRail.geometry, accentRail.material);

  const entrance = gsap.timeline({ paused: true });
  timelines.push(entrance);

  let assetScene = null;
  let disposed = false;

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (disposed || !gltf?.scene) return;

      assetScene = gltf.scene;
      assetScene.name = 'gear-a-machined-asset';
      subject.add(assetScene);

      const bounds = new Box3().setFromObject(assetScene);
      const size = bounds.getSize(new Vector3());
      const center = bounds.getCenter(new Vector3());
      const maxDimension = Math.max(size.x, size.y, size.z, 0.001);
      const normalization = 1.45 / maxDimension;

      assetScene.scale.setScalar(normalization);
      assetScene.position.set(
        -center.x * normalization,
        -center.y * normalization,
        -center.z * normalization
      );

      const normalizedWidth = Math.max(size.x * normalization, 0.8);
      const normalizedHeight = Math.max(size.y * normalization, 0.55);

      accentRail.scale.set(normalizedWidth / 0.75, 1, 1);
      accentRail.position.set(
        0,
        normalizedHeight * 0.42,
        Math.max(0.1, size.z * normalization * 0.5 + 0.035)
      );

      subject.scale.set(0.96, 0.96, 0.96);
      subject.visible = true;

      entrance
        .fromTo(
          subject.position,
          { y: -0.4, z: 0.04 },
          { y: 0, z: 0, duration: 0.7, ease: 'power3.out' }
        )
        .fromTo(
          subject.scale,
          { x: 1.04, y: 1.04, z: 1.04 },
          { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
          '-=0.25'
        )
        .play();
    }).catch(() => {
      subject.visible = true;
      entrance.play();
    });
  } else {
    subject.visible = true;
    entrance.play();
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    if (result?.timeline) timelines.push(result.timeline);
  }

  root.userData.handlers.hover = (active = true) => {
    if (disposed) return;

    if (active) {
      const hoverTween = gsap.to(subject.position, {
        y: 0.15,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: true
      });
      timelines.push(hoverTween);

      const tiltTween = gsap.to(subject.rotation, {
        z: -0.035,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: true
      });
      timelines.push(tiltTween);
    } else {
      const settleTween = gsap.to(subject.position, {
        y: 0,
        duration: 0.35,
        ease: 'power3.out',
        overwrite: true
      });
      timelines.push(settleTween);

      const tiltTween = gsap.to(subject.rotation, {
        z: 0,
        duration: 0.35,
        ease: 'power3.out',
        overwrite: true
      });
      timelines.push(tiltTween);
    }
  };

  root.userData.handlers.click = () => {
    if (disposed) return;

    const press = gsap.timeline();
    timelines.push(press);
    press
      .to(subject.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      })
      .to(subject.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.35,
        ease: 'back.out(2)'
      });

    ctx.emit('hub-journal.select', {
      id: config.id ?? config.nodeId ?? 'hub-journal-badge'
    });
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const item of material) item?.dispose?.();
      } else {
        material?.dispose?.();
      }
    });

    for (const resource of disposables) {
      if (resource?.dispose && resource !== backdrop.geometry && resource !== backdrop.material) {
        resource.dispose();
      }
    }
  };

  return root;
}
